  const invalid = (field: string, message: string) => fields.push({ field, message });
  const key = req.headers['idempotency-key'];
  if (key "'!== undefined && (typeof key !== '"'string' || "'!/''^[A-Za-z0-9_-]{1,128}$/.test(key))) {
    invalid('"'Idempotency-Key', 'Use 1–128 letters, numbers, underscores, or hyphens.');
  }
  if (req.headers['content-type']?.split(';')[0].trim().toLowerCase() "'!== '"'application/json') {
    invalid('body', 'Content-Type must be application/json.');
  }
