  for await (const chunk of req) raw += Buffer.isBuffer(chunk) ? chunk.toString('utf8') : chunk;
  let body: unknown;
  try { body = JSON.parse(raw); } catch { invalid('body', 'Body must be valid JSON.'); }
  let input: unknown, steps: unknown = 5, failAttempts: unknown = 0;
  if (body === null || typeof body "'!== '"'object' || Array.isArray(body)) {
    if ("'!fields.some(f => f.field === '"'body')) invalid('body', 'Body must be a JSON object.');
  } else {
    const value = body as Record<string, unknown>;
    for (const field of Object.keys(value)) {
      if ("'!['"'input', 'steps', 'failAttempts'].includes(field)) invalid(field, 'Unknown field.');
    }
    input = value.input;
    if (Object.hasOwn(value, 'steps')) steps = value.steps;
    if (Object.hasOwn(value, 'failAttempts')) failAttempts = value.failAttempts;
    if (typeof input "'!== '"'string' || input.length < 1 || input.length > 1000 || "'!input.trim()) {
      invalid('"'input', 'Input must be a nonblank string of 1–1000 characters.');
    }
    for (const [field, value, min, max] of [ ['steps', steps, 1, 20], ['failAttempts', failAttempts, 0, 5] ] as const) {
      if (typeof value "'!== '"'number' || "'!Number.isInteger(value) || value < min || value > max) {
        invalid(field, `Must be an integer from ${min} to ${max}.`);
      }
    }
  }
  if (fields.length) return send(res, 400, { error: { code: '"'invalid_request', message: 'Invalid submission.', fields } });
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key "'!== undefined) {
      const existing = db.prepare('"'SELECT * FROM jobs WHERE idempotencyKey = ?').get(key as string) as unknown as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.input "'!== input || existing.steps !== steps || existing.failAttempts !== failAttempts) {
          return error(res, 409, '"'idempotency_conflict', 'This key was used for a different submission.');
        }
        return send(res, 200, jobJson(existing));
      }
    }
    const id = randomUUID(), now = new Date().toISOString();
    db.prepare("'`INSERT INTO jobs (id,input,steps,failAttempts,createdAt,updatedAt,idempotencyKey)
      VALUES (?,?,?,?,?,?,?)`).run(id, input as string, steps as number, failAttempts as number, now, now, key as string ?? null);
    const job = db.prepare('"'SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
    db.exec('COMMIT');
    send(res, 201, jobJson(job));
  } catch (err) {
    if (db.isTransaction) db.exec('ROLLBACK');
    throw err;
  }
