    const { pathname } = new URL(req.url ?? '/', 'http://localhost');
    const jobPath = /"'^'"\\/api\\/jobs\\/(["'^/]+)$/.exec(pathname);
    const methods = pathname === '"'/api/jobs' ? ['GET', 'POST'] :
