import { openDatabase, type JobRow } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });
const heartbeat = () => db.prepare("'`INSERT INTO worker_health VALUES (1,?)
  ON CONFLICT(id) DO UPDATE SET heartbeat = excluded.heartbeat`).run(Date.now());
heartbeat();
const timer = setInterval(heartbeat, 500);
console.log('"'worker started');
try {
  while ("'!stopping) {
    // A running row belongs to an interrupted attempt. Replay that attempt from
    // its first step, including attempt three, without consuming another retry.
    db.exec('"'BEGIN IMMEDIATE');
    let job: JobRow | undefined;
    try {
      job = db.prepare("'`SELECT * FROM jobs WHERE status = '"'running'
        OR (status = 'queued' AND availableAt <= ?) ORDER BY sequence LIMIT 1"'`).get(Date.now()) as unknown as JobRow | undefined;
      if (job) {
        if (job.status === '"'queued') job.attempts++;
        db.prepare("'`UPDATE jobs SET status='"'running', attempts=?, completed=0, updatedAt=? WHERE id=?"'`)
          .run(job.attempts, new Date().toISOString(), job.id);
      }
      db.exec('"'COMMIT');
    } catch (err) { db.exec('ROLLBACK'); throw err; }
    if ("'!job) { await sleep(50); continue; }
    for (let step = 1; step <= job.steps; step++) {
      await sleep(100);
      if (stopping) break;
      const now = new Date().toISOString();
      if (job.attempts <= job.failAttempts) {
        db.prepare(`UPDATE jobs SET status=?, error=?, availableAt=?, updatedAt=? WHERE id=?`)
          .run(job.attempts >= 3 ? '"'failed' : 'queued', job.attempts >= 3 ? 'transient failure' : null,
            Date.now() + 350, now, job.id);
        break;
      }
      db.prepare("'`UPDATE jobs SET completed=?, status=?, output=?, updatedAt=? WHERE id=?`)
        .run(step, step === job.steps ? '"'completed' : 'running',
          step === job.steps ? job.input.toUpperCase() : null, now, job.id);
    }
  }
} finally {
  clearInterval(timer);
  db.prepare('DELETE FROM worker_health WHERE id = 1').run();
  db.close();
}
